{
  "items": [
    {
      "name": "ENNReal.monotone_rpow_of_nonneg",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.NNReal",
      "kind": "theorem",
      "type": "∀ {z : ℝ}, 0 ≤ z → Monotone fun x => x ^ z"
    },
    {
      "name": "ENNReal.rpow_le_rpow_of_exponent_le",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.NNReal",
      "kind": "theorem",
      "type": "∀ {x : ENNReal} {y z : ℝ}, 1 ≤ x → y ≤ z → x ^ y ≤ x ^ z"
    },
    {
      "name": "Real.rpow_le_rpow_left_iff",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y z : ℝ}, 1 < x → (x ^ y ≤ x ^ z ↔ y ≤ z)"
    },
    {
      "name": "Real.monotoneOn_rpow_Ici_of_exponent_nonneg",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {r : ℝ}, 0 ≤ r → MonotoneOn (fun x => x ^ r) (Set.Ici 0)"
    },
    {
      "name": "Real.rpow_le_rpow_of_exponent_le",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y z : ℝ}, 1 ≤ x → y ≤ z → x ^ y ≤ x ^ z"
    },
    {
      "name": "NNReal.monotone_nnrpow_const",
      "module_name": "Mathlib.Analysis.SpecialFunctions.ContinuousFunctionalCalculus.Rpow.Basic",
      "kind": "theorem",
      "type": "∀ (y : NNReal), Monotone fun x => x.nnrpow y"
    },
    {
      "name": "Real.rpow_le_rpow_of_exponent_le_or_ge",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y z : ℝ}, 1 ≤ x ∧ y ≤ z ∨ 0 < x ∧ x ≤ 1 ∧ z ≤ y → x ^ y ≤ x ^ z"
    },
    {
      "name": "Real.monotone_rpow_of_base_ge_one",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {b : ℝ}, 1 ≤ b → Monotone fun x => b ^ x"
    }
  ]
}
